(() => {
  const qa = (s) => [...document.querySelectorAll(s)];
  const body = document.body.innerText;
  if (!body.includes('重画森林图并核对置信区间')) throw new Error('the host conversation is not in the shared list');
  if (!body.includes('整理两篇文献的结论对比表')) throw new Error('the local conversation disappeared from the shared list');
  // A workspace heading names the host's own workspace. The host's *chats* are
  // not a heading of their own any more: a heading between two conversations of
  // the same hour made the list a user scans for "what is current" into one list
  // per machine to scan separately.
  const headings = qa("[data-testid='merged-group-heading']").map(n => (n.textContent || '').trim());
  if (!headings.includes('图表脚本')) throw new Error('the host workspace heading is missing: ' + headings.join('/'));
  if (headings.some(h => h.includes('iMac'))) throw new Error('chats are still split per machine: ' + headings.join('/'));
  // One chat section, both machines' chats, newest first across machines.
  const section = document.querySelector("[data-testid='merged-conversations']");
  if (!section) throw new Error('no chat section');
  const text = section.innerText;
  const order = ['基金申报书的创新点怎么写', '审稿意见逐条回复草稿', '解释一下 p 值的常见误用'].map(t => text.indexOf(t));
  if (order.some(i => i < 0)) throw new Error('a chat is missing from the chat section: ' + order.join(','));
  if (!(order[0] < order[1] && order[1] < order[2])) throw new Error('chats are not interleaved by time: ' + order.join(','));
  // The machine's icon rides with the title it qualifies, not at the row's right
  // edge. Measured, because "beside the title" is a distance and a class list
  // cannot express one: these icons sat at the far edge of the rail twice.
  const rowGaps = qa("[data-testid='remote-source-icon']").map((b) => {
    const row = b.closest("div[class*='group/thread']");
    const title = row ? [...row.querySelectorAll('span')].find(s => (s.textContent || '').length > 4 && s !== b) : null;
    return title ? Math.round(b.getBoundingClientRect().left - title.getBoundingClientRect().right) : 999;
  });
  if (rowGaps.length === 0) throw new Error('no remote row says which machine it is on');
  if (rowGaps.some(gap => gap > 12)) throw new Error('a row icon is away from its title: ' + rowGaps.join(','));
  const headGaps = qa("[data-testid='merged-group-heading']").map((name) => {
    const header = name.closest('div');
    const icon = [...header.querySelectorAll('span[aria-hidden]')].find(s => (s.textContent || '').trim() !== '');
    return icon ? Math.round(icon.getBoundingClientRect().left - name.getBoundingClientRect().right) : 0;
  });
  if (headGaps.some(gap => gap > 12)) throw new Error('a heading icon is away from its name: ' + headGaps.join(','));

  // A group is placed by the *workspace's* own last-touched time, never by its
  // conversations'. This machine's folder was opened two minutes ago and the
  // host's thirty, while the host's newest conversation (90s ago) is newer than
  // anything under the local heading: a list that ranked groups by their rows
  // put the host's group first, and moved it the moment a reply landed in it.
  const headerOrder = qa("[data-testid='local-group-heading'], [data-testid='merged-group-heading']")
    .map(n => (n.textContent || '').trim());
  const headerAt = (name) => headerOrder.findIndex(h => h === name);
  if (headerAt('多巴胺与决策') < 0 || headerAt('图表脚本') < 0)
    throw new Error('a workspace heading is missing: ' + headerOrder.join('/'));
  if (headerAt('多巴胺与决策') > headerAt('图表脚本'))
    throw new Error('groups are ordered by their conversations, not by the workspace: ' + headerOrder.join('/'));

  // A conversation on that host that has a fork is a row with a fold toggle in
  // front of its title, and the fork is folded away until it is asked for.
  if (body.includes('把森林图改成黑白版'))
    throw new Error('the fork is on screen before its parent is unfolded');
  const foldToggle = document.querySelector("button[aria-label='展开 重画森林图并核对置信区间 的子对话']");
  if (!foldToggle) throw new Error('the host conversation has no fold toggle');
  const parentRow = foldToggle.closest("div[class*='group/thread']");
  const parentTitle = parentRow
    ? [...parentRow.querySelectorAll('span')].find(s => (s.textContent || '').includes('重画森林图'))
    : null;
  if (!parentTitle || !(foldToggle.compareDocumentPosition(parentTitle) & Node.DOCUMENT_POSITION_FOLLOWING))
    throw new Error('the fold toggle is not in front of the title it folds');
})()

(() => {
  const msgs = [...document.querySelectorAll('[data-message-id]')];
  if (msgs.length < 2) throw new Error('the transcript did not render: ' + msgs.length);

  // The author line: one per turn, above the text. A transcript that rendered the
  // host's raw entries had one above every *fragment* — a column of "assistant".
  const authors = msgs.map(m => (m.innerText || '').split('\n')[0].replace(/\s+/g, ' ').trim().slice(0, 12));
  if (authors.some(a => !a)) throw new Error('a turn has no author line: ' + JSON.stringify(authors));
  const speaker = (label) => authors.filter(a => a.includes(label)).length;
  if (speaker('你') < 1 || speaker('未来助手') < 1) throw new Error('the transcript is not a conversation: ' + JSON.stringify(authors));

  // One reading column, at this app's width.
  const boxes = msgs.map(m => { const r = m.getBoundingClientRect(); return Math.round(r.left) + ',' + Math.round(r.width); });
  if (new Set(boxes).size !== 1) throw new Error('turns are not one column: ' + boxes.join(' | '));

  // The header: this app's own, 48px, carrying the conversation's usage.
  const header = document.querySelector('header');
  const h = header.getBoundingClientRect();
  if (Math.round(h.height) !== 48) throw new Error('header is not 48px: ' + h.height);
  const headerLabels = [...header.querySelectorAll('button')].map(b => b.getAttribute('aria-label') || '');
  if (header.querySelector("[data-testid='remote-thread-usage']") === null)
    throw new Error('no usage action in the header: ' + headerLabels.join('|'));
  // Compacting is a request, and it lives behind `/` in the composer.
  if (headerLabels.some(l => l.includes('压缩上下文')))
    throw new Error('compact is still a header button: ' + headerLabels.join('|'));

  // The right panel is this conversation's files: the collapsed affordance is a
  // button over the header, and opening it lists that host's files.
  const filesToggle = document.querySelector("button[aria-label='显示此对话的文件']")
    || document.querySelector("button[aria-label=\"Show this conversation's files\"]");
  if (!filesToggle) throw new Error('no files affordance for a remote conversation');

  // The composer: this app's shell, the same width as the messages above it.
  const form = document.querySelector('form');
  if (!form) throw new Error('no composer');
  const cls = form.className || '';
  for (const part of ['rounded-lg', 'shadow-panel', 'border-line']) {
    if (!cls.includes(part)) throw new Error('composer shell is not the local one: missing ' + part);
  }
  const f = form.getBoundingClientRect();
  const firstMessage = msgs[0].getBoundingClientRect();
  if (Math.abs(f.width - firstMessage.width) > 2)
    throw new Error('the composer is not as wide as the messages: ' + Math.round(f.width) + ' vs ' + Math.round(firstMessage.width));
  const attach = form.querySelector("button[aria-label='添加附件']") || form.querySelector("button[aria-label='Attach']");
  // Found by its accessible name: this app's send control is an icon button.
  const send = form.querySelector("button[aria-label='发送']") || form.querySelector("button[aria-label='Send']");
  if ((send?.textContent || '').trim() !== '') throw new Error('send still carries a label: ' + send.textContent);
  if (!attach || !send) throw new Error('composer controls missing: ' + (attach ? '' : 'attach ') + (send ? '' : 'send'));
  const a = attach.getBoundingClientRect();
  const s = send.getBoundingClientRect();
  if (a.left > f.left + f.width / 2) throw new Error('attach is not at the left');
  if (s.right < f.left + f.width / 2) throw new Error('send is not at the right');
  // The field is the local composer's shape: a textarea the shell borders, rather than a bordered control nested inside the shell.
  const field = form.querySelector('textarea');
  if (!field) throw new Error('the field is not a textarea');
  if ((field.className || '').includes('border')) throw new Error('the field draws its own border inside the shell');
  for (const part of ['min-h-14', 'px-2', 'py-1', 'text-sm']) {
    if (!(field.className || '').includes(part)) throw new Error('the field is not the local one: missing ' + part);
  }
  // The placeholder is this app's own, minus the `@` (a remote prompt attaches files
  // with the paperclip, by id) and never naming the machine: the box describes the
  // task, exactly as the local composer does.
  if (field.placeholder !== '描述任务，按 / 使用工具或技能')
    throw new Error('the placeholder does not match the local composer: ' + field.placeholder);

  // The model and thinking controls are this app's own dropdowns, not native selects.
  if (form.querySelector('select')) throw new Error('the control row still uses a native select');

  // The transcript clears the composer. The composer rides *over* the transcript
  // behind a fade rather than sitting under it, so the footer's own height is
  // reserved at the end of the content; without it the last turn is drawn under
  // the input box, which is what "the bottom of the conversation is cut off"
  // looks like. Measured, because that is a distance and no class list says it.
  const scroller = document.querySelector("[data-chat-scroll='true']");
  scroller.scrollTop = scroller.scrollHeight;
  const lastTurn = [...document.querySelectorAll('[data-message-id]')].pop();
  const covered = Math.round(lastTurn.getBoundingClientRect().bottom - form.getBoundingClientRect().top);
  if (covered > 0)
    throw new Error('the last turn is under the composer by ' + covered + 'px');
})()

(() => {
  const overlay = document.querySelector("[data-preview-overlay], img[alt='forest-plot.png']");
  const image = document.querySelector("img[alt='forest-plot.png']");
  if (!image) throw new Error('the preview overlay is not showing the file');
  if (!(image.getAttribute('src') || '').includes('forest-plot.png'))
    throw new Error('the image is not the fetched file: ' + image.getAttribute('src'));
  // Nothing asked the user where to put a copy: looking at a file is not saving it.
  if (document.querySelector("[role='dialog']"))
    throw new Error('a dialog is open over the preview');
  // The panel keeps the file it opened, and the types it will not open are still
  // the download control's.
  const panel = [...document.querySelectorAll('aside')].find(node => (node.textContent || '').includes('forest-plot.png'));
  if (!panel) throw new Error('the file panel is gone');
  const zip = [...panel.querySelectorAll('button')].find(node => (node.textContent || '').trim() === 'archive.zip');
  if (!zip || !zip.disabled) throw new Error('a file the overlay cannot render is offered as a preview');
  return image.getAttribute('src');
})()

(() => {
  // Poll rather than sleep: the host's frames arrive over a couple of seconds and
  // the harness's own click is not instant. What is asserted is unchanged — the
  // reply is on screen while its row is still the *live* one.
  const deadline = Date.now() + 8000;
  return new Promise((resolve, reject) => {
    const check = () => {
      const rows = [...document.querySelectorAll('[data-message-id]')];
      const live = rows.filter(row => (row.getAttribute('data-message-id') || '').startsWith('stream_'));
      if (live.length === 1 && (live[0].innerText || '').includes('置信区间确实画成了 90%')) {
        try {
          const text = live[0].innerText || '';
          // The run's work, folded into this app's own activity line: one tool call
          // and one reasoning block, inline in the reply.
          const line = live[0].querySelector('button[aria-label*="工具调用"], button[aria-label*="tool"]');
          if (!line) throw new Error('the live reply has no inline activity line: ' + text.slice(0, 200));
          const label = line.getAttribute('aria-label') || '';
          if (!label.includes('工具调用') || !label.includes('思考'))
            throw new Error('the live reply did not fold the run\'s work: ' + label);
          if (live[0] !== rows[rows.length - 1]) throw new Error('the live reply is not the last row');
          // The question it answers is above it, so the reply is not drawn alone.
          if (!rows.slice(0, -1).some(row => /森林图/.test(row.innerText || '')))
            throw new Error('the question the reply answers is not in the transcript');
          resolve('live row: ' + text.replace(/\s+/g, ' ').slice(0, 120));
        }
        catch (error) {
          reject(error);
        }
        return;
      }
      if (Date.now() > deadline) {
        reject(new Error('the reply never streamed: ' + rows.length + ' rows, live=' + live.length));
        return;
      }
      setTimeout(check, 150);
    };
    check();
  });
})()

(() => {
  const rows = [...document.querySelectorAll('[data-message-id]')];
  const live = rows.filter(row => (row.getAttribute('data-message-id') || '').startsWith('stream_'));
  if (live.length !== 0) throw new Error('the live reply outlived its run: ' + live.length);
  const text = rows.map(row => row.innerText || '').join('\n');
  if (!text.includes('并核对了每个效应的数值')) throw new Error('the settled reply is missing: ' + text.slice(0, 300));
  const occurrences = text.split('置信区间确实画成了 90%').length - 1;
  if (occurrences !== 1) throw new Error('the reply is drawn ' + occurrences + ' times');
  return 'settled rows: ' + rows.length;
})()

