(() => {
  const field = document.querySelector('textarea');
  // The placeholder describes the task and points at `/`, as this app's own
  // composer does. What it must not do is name the machine: that is the rail's
  // business, and this app's composers never state it.
  if (field.placeholder !== '描述任务，按 / 使用工具或技能')
    throw new Error('the placeholder does not match the local composer: ' + field.placeholder);
  const rows = [...document.querySelectorAll("[role='option']")].map(r => (r.textContent || '').trim());
  // The compact request leads, as this app's own context tool does.
  if (!rows[0].startsWith('压缩上下文')) throw new Error('the compact command does not lead: ' + JSON.stringify(rows));
  // Then the host's skills, by the name the host resolves, each with what it
  // does — a list of bare names is not a menu anyone can choose from.
  const skill = rows.find(r => r.startsWith('/Paper Search'));
  if (!skill) throw new Error('the host skills are not in the menu: ' + JSON.stringify(rows));
  if (!skill.includes('检索文献')) throw new Error('a skill row carries no description: ' + skill);
  // Above the box, not over it: the box sits at the foot of the window.
  const menu = document.querySelector("[role='listbox']");
  const box = document.querySelector('form');
  if (!menu || !box) throw new Error('no menu over the box');
  if (menu.getBoundingClientRect().bottom > box.getBoundingClientRect().top + 1)
    throw new Error('the menu opens over the box instead of above it');
  return rows.length + ' rows';
})()

(() => {
  const byLabel = (needle) => [...document.querySelectorAll('button')]
    .find(node => (node.getAttribute('aria-label') || '').includes(needle));
  const model = byLabel('使用的模型');
  const level = byLabel('思考等级');
  if (!model || !level) throw new Error('the draft has no model/level pickers');
  // Enabled means the host's catalogue arrived: an empty catalogue disables it.
  if (model.disabled) throw new Error('the model picker is disabled — no catalogue for a draft');
  const modelText = (model.textContent || '').trim();
  if (!modelText) throw new Error('the model picker shows nothing');
  const levelText = (level.textContent || '').trim();
  // The level a new conversation on that host runs with. "关闭"/"Off" is the old
  // fallback, which is not a default anybody chose.
  if (!levelText || /^(关闭|Off)$/.test(levelText))
    throw new Error('the thinking level is not the host default: ' + levelText);
  return 'model=' + modelText + ' level=' + levelText;
})()

