(() => {
  const add = [...document.querySelectorAll("button[aria-label='新建对话'], button[aria-label='New chat']")][0];
  if (!add) throw new Error('the chat section offers no way to start a conversation');
  add.click();
  return new Promise((resolve) => {
    setTimeout(() => {
      const items = [...document.querySelectorAll("[role='menuitem']")].map(node => (node.textContent || '').trim());
      if (items.length < 2) throw new Error('the control did not ask which machine: ' + JSON.stringify(items));
      if (!items.some(label => label.includes('本机') || label.includes('本电脑')))
        throw new Error('this machine is not offered: ' + JSON.stringify(items));
      if (!items.some(label => label.includes('iMac')))
        throw new Error('the paired machine is not offered: ' + JSON.stringify(items));
      resolve(items.join(' / '));
    }, 250);
  });
})()

